+export const clamp=(x,a=0,b=1)=>Math.max(a,Math.min(b,x));
+export const ease=x=>{const a=clamp(x); return a*a*(3-2*a);};
+export const lerp=(a,b,x)=>a+(b-a)*x;
+const score=makeScore();
