+function impulse(t,voices) {
+  let sum=0;
+  for(const e of score) {
+    const d=t-e.time;
+    if(voices.includes(e.voice)&&d>=0&&d<1.4) sum+=e.amp*Math.exp(-d*6.5)*(1-Math.exp(-d*95));
+  }
+  return sum;
+}
