+ while(t<235){const rr=average*(.80+r()*.39),p={time:t,rr,height:.78+r()*.45,width:.023+r()*.014,p:.065+r()*.13,q:.14+r()*.19,s:.24+r()*.35,tail:.12+r()*.25,skew:(r()-.5)*.06};beats.push(p);t+=rr;}
